SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(a),'relation',to_jsonb(pg_identify_object('pg_class'::regclass,a.attrelid,0)),'column_identity',CASE WHEN NOT a.attisdropped THEN to_jsonb(pg_identify_object('pg_class'::regclass,a.attrelid,a.attnum)) END,'formatted_type',CASE WHEN a.atttypid<>0 THEN format_type(a.atttypid,a.atttypmod) END,'type',CASE WHEN a.atttypid<>0 THEN to_jsonb(pg_identify_object('pg_type'::regclass,a.atttypid,0)) END,'collation',CASE WHEN a.attcollation<>0 THEN to_jsonb(pg_identify_object('pg_collation'::regclass,a.attcollation,0)) END) ORDER BY a.attrelid,a.attnum),'[]'::jsonb) AS payload FROM pg_attribute a WHERE a.attrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace UNION SELECT reltoastrelid FROM pg_class WHERE relnamespace='public'::regnamespace AND reltoastrelid<>0 UNION SELECT i.indexrelid FROM pg_index i JOIN pg_class c ON c.reltoastrelid=i.indrelid WHERE c.relnamespace='public'::regnamespace)) AS capture